CONST_BLOCK=('\n                ; Исходная граница записи первого байтового кода\n                module ActionCodeStepConst\n'+
    'FirstMinDiff'.ljust(16)+'equ #02'.ljust(64)+'; первый код записывается только при модуле разности не меньше двух\n'
    '                endmodule\n\n')
STRUCT_BLOCK='\n                ; Динамические вложенные рамки основного StepRecordTargetCodes, память не выделяется\n'
for name,child,size in (('FRecordStepRootFrame','FDeltaCodeRootFrame',18),('FRecordStepFirstFrame','FDeltaCodeFirstFrame',18),
                        ('FRecordStepSecondFrame','FDeltaCodeSecondFrame',16)):
    STRUCT_BLOCK+='                struct '+name+'\n'
    STRUCT_BLOCK+='ChildFrame'.ljust(16)+child.ljust(64)+'; реальная рамка дочерней геометрии, её внешний возврат равен 6268\n'
    STRUCT_BLOCK+='CallerReturn'.ljust(16)+'dw #0000'.ljust(64)+'; внешний возврат вызывающего StepRecordTargetCodes\n'
    STRUCT_BLOCK+='                ends\n                assert '+name+' == #'+format(size,'02X')+'\n\n'


def name_operands(region,address,operation):
    if (region,address)!=('Action',0x6265):return operation
    for value,field in ((0x08,'OffsetPhase1'),(0x09,'OffsetPhase2'),(0x25,'TargetCodeStep')):
        operation=operation.replace('(IX+#'+format(value,'02X')+')','(IX + @FActionRecord.'+field+')')
    return operation.replace('CP #02','CP @ActionCodeStepConst.FirstMinDiff')
